import{_ as s,o as n,c as e,ag as p}from"./chunks/framework.DUTPmUpA.js";const i="/_assets/78Z3kaV.CpaRpKki.png",t="/_assets/lhQL0-81b3632bad.CLEL-LzF.png",o="/_assets/lhRLL-31d63b48d9.B_WfF7Pp.jpg",l="/_assets/lhQFp-37192e1e63.LMMJVVbW.jpg",g=JSON.parse('{"title":"Пользовательские значки мини-карты","description":"","frontmatter":{"title":"Пользовательские значки мини-карты","author":"Noya","steamId":"76561198046984233","date":"11.11.2015"},"headers":[],"relativePath":"assets/custom-minimap-icons.md","filePath":"assets/custom-minimap-icons.md"}'),r={name:"assets/custom-minimap-icons.md"};function c(u,a,d,m,b,h){return n(),e("div",null,[...a[0]||(a[0]=[p('<p>ьские значки мини-карты</p><p>Вот быстрое и простое пошаговое руководство о том, как создавать и использовать собственные значки существ на мини-карте.</p><h2 id="шаг-1-получите-фаилы" tabindex="-1">Шаг 1. Получите файлы <a class="header-anchor" href="#шаг-1-получите-фаилы" aria-label="Permalink to &quot;Шаг 1. Получите файлы&quot;">​</a></h2><p><a href="https://drive.google.com/file/d/1nsisy1oPKXsGR3LFhfRjBhwQIp9A7jY2/view?usp=sharing" target="_blank" rel="noreferrer">minimap_icon.zip</a></p><p>Он содержит следующие файлы:</p><ul><li><strong><code>addon_hud_textures.txt</code></strong></li><li><strong><code>vgui/hud/minimap_icon.txt</code></strong></li><li><strong><code>vgui/hud/minimap_icon.vmat</code></strong></li><li><strong><code>vgui/hud/minimap_icon.psd</code></strong></li></ul><p><code>addon_hud_textures.txt</code> — это уникальный файл, определяющий пути для каждого пользовательского значка.</p><p>3 файла <code>minimap_icon</code> используются вместе, и их следует переименовать в имя вашего будущего значка, например <code>_minimap_questgiver_</code> или <code>_boss_kappa_</code>.</p><h2 id="шаг-2-отредактируите-фаилы" tabindex="-1">Шаг 2. Отредактируйте файлы <a class="header-anchor" href="#шаг-2-отредактируите-фаилы" aria-label="Permalink to &quot;Шаг 2. Отредактируйте файлы&quot;">​</a></h2><h3 id="psd-изображение" tabindex="-1">PSD-изображение <a class="header-anchor" href="#psd-изображение" aria-label="Permalink to &quot;PSD-изображение&quot;">​</a></h3><p>Используйте графический редактор, например Photoshop или GIMP, для редактирования PSD-файла.</p><p>В исходном файле примера я быстро сделал вот такое прозрачное изображение из <a href="/images/external/x3L74Hw.png">this source</a>:</p><p><img src="'+i+'" alt="img"></p><p>Рекомендуемый размер изображения: <strong>64x64</strong>.<br>. Если вы хотите использовать другой размер изображения, он <strong>должен быть степенью двойки</strong>.</p><p>::: предупреждение Вам нужно, чтобы альфа-слой был заполнен прозрачной фигурой, которую вы хотите отобразить: ::: <img src="'+t+`" alt="img"></p><p>Для получения лучших результатов добавьте к изображению четкие черные рамки в качестве контура (и не забудьте соответствующим образом обновить альфа-слой).</p><h3 id="материал-vmat" tabindex="-1">Материал VMAT <a class="header-anchor" href="#материал-vmat" aria-label="Permalink to &quot;Материал VMAT&quot;">​</a></h3><p>Откройте <code>.vmat</code> в любом редакторе кода и обязательно замените <code>minimap_icon.psd</code> на имя по вашему выбору. Остальное оставьте без изменений</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Layer0&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;Shader&quot;            &quot;ui.vfx&quot;</span></span>
<span class="line"><span>    &quot;F_STENCIL_MASKING&quot; &quot;1&quot;</span></span>
<span class="line"><span>    &quot;Texture&quot;           &quot;materials/vgui/hud/minimap_icon.psd&quot;</span><span> //EDIT THIS</span></span>
<span class="line"><span>    &quot;F_TRANSLUCENT&quot;     &quot;1&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="текстурныи-фаил-kv" tabindex="-1">Текстурный файл KV <a class="header-anchor" href="#текстурныи-фаил-kv" aria-label="Permalink to &quot;Текстурный файл KV&quot;">​</a></h3><p>Тот же процесс в файле <code>addon_hud_textures.txt</code>.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;TextureData&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;minimap_icon&quot;</span><span> //EDIT THIS</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;file&quot;     &quot;materials/vgui/hud/minimap_icon.vmat&quot;</span><span> //EDIT THIS</span></span>
<span class="line"><span>            &quot;x&quot;        &quot;0&quot;</span></span>
<span class="line"><span>            &quot;y&quot;        &quot;0&quot;</span></span>
<span class="line"><span>            &quot;width&quot;    &quot;64&quot;</span></span>
<span class="line"><span>            &quot;height&quot;   &quot;64&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>Чтобы получить больше значков, просто скопируйте блок minimap_icon еще раз с другим именем внутри TextureData.</p><h2 id="шаг-3-переместите-фаилы" tabindex="-1">Шаг 3. Переместите файлы <a class="header-anchor" href="#шаг-3-переместите-фаилы" aria-label="Permalink to &quot;Шаг 3. Переместите файлы&quot;">​</a></h2><ul><li><p>Файлы <strong>minimap_icon</strong> находятся в папке <strong>content</strong>/dota_addons/YOUR_ADDON/materials/<strong>vgui/hud/</strong>.</p></li><li><p>Файл <strong>addon_hud_textures.txt</strong> находится в папке <strong>game</strong>/dota_addons/YOUR_ADDON/scripts/.</p></li></ul><h2 id="шаг-4-скомпилируите-и-проверьте" tabindex="-1">Шаг 4. Скомпилируйте и проверьте <a class="header-anchor" href="#шаг-4-скомпилируите-и-проверьте" aria-label="Permalink to &quot;Шаг 4. Скомпилируйте и проверьте&quot;">​</a></h2><p>Зайдите в браузер ресурсов, напишите имя вашего значка, откройте vmat, дважды щелкнув по нему (это скомпилирует его).</p><p><img src="`+o+`" alt="img"></p><h2 id="шаг-5-настроите-свое-устроиство-на-использование-нового-значка" tabindex="-1">Шаг 5. Настройте свое устройство на использование нового значка <a class="header-anchor" href="#шаг-5-настроите-свое-устроиство-на-использование-нового-значка" aria-label="Permalink to &quot;Шаг 5. Настройте свое устройство на использование нового значка&quot;">​</a></h2><p>В определении модуля добавьте следующие строки:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;MinimapIcon&quot;        &quot;minimap_icon&quot;</span></span>
<span class="line"><span>&quot;MinimapIconSize&quot;    &quot;1000&quot;</span></span>
<span class="line"><span>&quot;MinimapDisableTint&quot; &quot;1&quot;</span></span>
<span class="line"><span>\`</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>MinimapIconSize<code>определяет относительный размер значка на мини-карте, а</code>MinimapDisableTint\` может быть равен 0 или опущен, если вы хотите, чтобы существо использовало разные цвета команды.</p><h2 id="шаг-6-попробуите-в-игре" tabindex="-1">Шаг 6. Попробуйте в игре <a class="header-anchor" href="#шаг-6-попробуите-в-игре" aria-label="Permalink to &quot;Шаг 6. Попробуйте в игре&quot;">​</a></h2><p><img src="`+l+'" alt="img"></p>',34)])])}const _=s(r,[["render",c]]);export{g as __pageData,_ as default};
